    pan_positions: Dict[str, float] = field(default_factory=dict)  # track_id -> pan (-1.0 to 1.0)
    start_times: Dict[str, float] = field(default_factory=dict)  # track_id -> offset in ms
    loop: bool = False
    loop_start_ms: float = 0.0
    loop_end_ms: float = 0.0

    def to_dict(self):
        return {
            "track_ids": self.track_ids,
            "effects": self.effects,
            "volume_levels": self.volume_levels,
            "pan_positions": self.pan_positions,
            "start_times": self.start_times,
            "loop": self.loop,
            "loop_start_ms": self.loop_start_ms,
            "loop_end_ms": self.loop_end_ms
        }

@dataclass
class Mashup:
    mashup_id: str
    room_id: str
    creator_id: str
    name: str
    state: MashupState
    created_at: datetime = field(default_factory=lambda: datetime.now(timezone.utc))
    updated_at: datetime = field(default_factory=lambda: datetime.now(timezone.utc))
    vote_count: int = 0
    is_deleted: bool = False

    def to_dict(self):
        return {
            "mashup_id": self.mashup_id,
            "room_id": self.room_id,
            "creator_id": self.creator_id,
            "name": self.name,
            "state": self.state.to_dict(),
            "created_at": self.created_at.isoformat(),
            "updated_at": self.updated_at.isoformat(),
            "vote_count": self.vote_count,
            "is_deleted": self.is_deleted
        }

@dataclass
class ChatMessage:
