@dataclass
class Room:
    room_id: str
    name: str
    is_private: bool
    owner_id: str
    participants: Set[str] = field(default_factory=set)
    mashups: List[str] = field(default_factory=list)  # mashup_ids
    chat_history: List[str] = field(default_factory=list)  # message_ids
